import logo from './logo.svg';
import './App.css';
import React from "react";
import ReactDOM from 'react-dom';

function employeeLogin() {
  return (
    <body className='body'>
      <div className="page">
        <form>
          <h2>Welcome</h2>
          <h3>Create your Account</h3>
          <label>
            Username
            <input 
            type = "text"
            value = "Enter your username"
            />
          </label><br></br>
          <label>
            Email Adress
            <input 
            type = "email"
            value = "Enter your email"
            />
          </label><br></br>
          <label>
            Phone Number
            <input 
            type = "number"
            value = "Enter your phone number"
            />
          </label><br></br>
          <label>
            Password
            <input 
            type = "text"
            value = "Enter your password"
            />
          </label><br></br>
          <label>
            Confirm Password
            <input 
            type = "text"
            value = "Re-enter the password"
            />
          </label>
        </form>
    </div>
    </body>

  );
}


